import pandas as pd

def clean(df):
    df = df.copy()
    if 'species' in df.columns:
        df['species'] = df['species'].astype('string').str.strip()
        df['species'] = df['species'].replace({'Chinstarp': 'Chinstrap'})
    if 'island' in df.columns:
        df['island'] = df['island'].astype('string').str.strip()
    df = df.drop_duplicates()
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce').abs()
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island')['penguin_id'].nunique()
    return {str(k): int(v) for k, v in counts.items()}
